    fn print_horizontal_line_term(
        &mut self,
        handle: &mut OutputHandle,
        style: Style,
    ) -> Result<()> {
        writeln!(
            handle,
            "{}",
            style.paint("─".repeat(self.config.term_width))
        )?;
        Ok(())
    }

    fn print_horizontal_line(&mut self, handle: &mut OutputHandle, grid_char: char) -> Result<()> {
        if self.panel_width == 0 {
            self.print_horizontal_line_term(handle, self.colors.grid)?;
        } else {
            let hline = "─".repeat(self.config.term_width - (self.panel_width + 1));
            let hline = format!("{}{}{}", "─".repeat(self.panel_width), grid_char, hline);
            writeln!(handle, "{}", self.colors.grid.paint(hline))?;
        }

        Ok(())
    }

    fn create_fake_panel(&self, text: &str) -> String {
        if self.panel_width == 0 {
            return "".to_string();
        }

        let text_truncated: String = text.chars().take(self.panel_width - 1).collect();
        let text_filled: String = format!(
            "{}{}",
            text_truncated,
            " ".repeat(self.panel_width - 1 - text_truncated.len())
        );
        if self.config.style_components.grid() {
            format!("{} │ ", text_filled)
        } else {
            text_filled
        }
    }

    fn print_header_component_indent(&mut self, handle: &mut OutputHandle) -> Result<()> {
        if self.config.style_components.grid() {
            write!(
                handle,
                "{}{}",
                " ".repeat(self.panel_width),
                self.colors
                    .grid
                    .paint(if self.panel_width > 0 { "│ " } else { "" }),
            )
        } else {
            write!(handle, "{}", " ".repeat(self.panel_width))
        }
    }

    fn preprocess(&self, text: &str, cursor: &mut usize) -> String {
        if self.config.tab_width > 0 {
            return expand_tabs(text, self.config.tab_width, cursor);
        }

        *cursor += text.len();
        text.to_string()
    }
}


macro_rules! write_output {
    ($handle:expr, $($arg:tt)*) => {
        write!($handle, $($arg)*)?
    };
}

macro_rules! write_grid_line {
    ($printer:expr, $handle:expr, $grid_char:expr) => {{
        if $printer.panel_width == 0 {
            write_output!(
                $handle,
                "{}\n",
                $printer.colors.grid.paint("─".repeat($printer.config.term_width))
            );
        } else {
            let rest = "─".repeat($printer.config.term_width - ($printer.panel_width + 1));
            let line = format!(
                "{}{}{}",
                "─".repeat($printer.panel_width),
                $grid_char,
                rest
            );
            write_output!($handle, "{}\n", $printer.colors.grid.paint(line));
        }
    }};
}

impl<'a> Printer for InteractivePrinter<'a> {
    fn print_header(
        &mut self,
        handle: &mut OutputHandle,
        input: &OpenedInput,
        add_header_padding: bool,
    ) -> Result<()> {
        let style_set = &self.config.style_components.0;
        let has_rule = style_set.contains(&StyleComponent::Rule);
        let has_grid = style_set.contains(&StyleComponent::Grid);
        let has_header_filename = style_set.contains(&StyleComponent::HeaderFilename);
        let has_header_filesize = style_set.contains(&StyleComponent::HeaderFilesize);
        let decoration_width: usize = self.decorations.iter().map(|decoration| decoration.width()).sum();
        let indent_width = [self.panel_width, decoration_width][usize::from(self.decorations.is_empty())];
        let bar = ["", "│ "][usize::from(has_grid) * usize::from(indent_width > 0)];
        let painted_bar = self.colors.grid.paint(bar).to_string();
        let component_indent = format!("{}{}", " ".repeat(indent_width), ["", painted_bar.as_str()][usize::from(has_grid)]);

        if add_header_padding {
            if has_rule {
                write_output!(handle, "{}\n", self.colors.rule.paint("─".repeat(self.config.term_width)));
            }
        }

        if !(has_header_filename || has_header_filesize) {
            if Some(ContentType::BINARY) == self.content_type {
                if !self.config.show_nonprintable {
                    let description = &input.description;
                    match description.summary() {
                        summary => {
                            write_output!(
                                handle,
                                "{}: Binary content from {} will not be printed to the terminal \
                                 (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                                 to show the binary file contents.\n",
                                Yellow.paint("[bat warning]"),
                                summary,
                            );
                        }
                    }
                    return Ok(());
                }
            }
            if has_grid {
                write_grid_line!(self, handle, '┬');
            }
            return Ok(());
        }

        let mode = [
            (Some(ContentType::BINARY), "   <BINARY>"),
            (Some(ContentType::UTF_16LE), "   <UTF-16LE>"),
            (Some(ContentType::UTF_16BE), "   <UTF-16BE>"),
        ]
        .iter()
        .find(|(content_type, _)| *content_type == self.content_type)
        .map(|(_, label)| *label)
        .unwrap_or(if self.content_type.is_none() { "   <EMPTY>" } else { "" });

        let description = &input.description;
        let metadata = &input.metadata;
        let mapped_syntax = input.path().and_then(|path| self.config.syntax_mapping.get_syntax_for(path));
        let mapped_label = mapped_syntax.and_then(|_| None::<String>).unwrap_or_default();

        if has_grid {
            write_grid_line!(self, handle, '┬');
        } else if add_header_padding {
            if !has_rule {
                write_output!(handle, "\n");
            }
        }

        if has_header_filename {
            write_output!(handle, "{}", component_indent);
            let title = match &description.title {
                Some(title) => title.as_str(),
                None => description.name.as_str(),
            };
            let kind_prefix = description.kind.as_ref().map(|kind| format!("{}: ", kind)).unwrap_or_else(String::new);
            write_output!(handle, "{}{}{}{}\n", kind_prefix, self.colors.header_value.paint(title), mode, mapped_label);
        }

        if has_header_filesize {
            write_output!(handle, "{}", component_indent);
            let bsize = metadata.size.map(|size| format!("{}", ByteSize(size))).unwrap_or("-".to_string());
            write_output!(handle, "Size: {}\n", self.colors.header_value.paint(bsize));
        }

        if has_grid {
            let separator = if self.content_type.map_or(false, |content_type| content_type.is_text()) {
                '┼'
            } else if self.config.show_nonprintable {
                '┼'
            } else {
                '┴'
            };
            write_grid_line!(self, handle, separator);
        }

        Ok(())
    }

    fn print_footer(&mut self, handle: &mut OutputHandle, _input: &OpenedInput) -> Result<()> {
        if self.config.style_components.grid()
            && (self.content_type.map_or(false, |c| c.is_text()) || self.config.show_nonprintable)
        {
            self.print_horizontal_line(handle, '┴')
        } else {
            Ok(())
        }
    }

